import{_ as e,o as t,c as o,a5 as n}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"HJ94 记票统计","description":"描述 请实现一个计票统计系统。你会收到很多投票，其中有合法的也有不合法的，请统计每个候选人得票的数量以及不合法的票数。 （注：不合法的投票指的是投票的名字不存在n个候选人的名字中！！） 数据范围：每组输入中候选人数量满足 1≤ n ≤100 ，总票数量满足 1≤ n ≤100 输。","frontmatter":{"title":"HJ94 记票统计","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"描述 请实现一个计票统计系统。你会收到很多投票，其中有合法的也有不合法的，请统计每个候选人得票的数量以及不合法的票数。 （注：不合法的投票指的是投票的名字不存在n个候选人的名字中！！） 数据范围：每组输入中候选人数量满足 1≤ n ≤100 ，总票数量满足 1≤ n ≤100 输。","sidebarWeight":68,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/华为简单[31个]/HJ94 记票统计.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/华为简单[31个]/HJ94 记票统计.md","filePath":"posts/前端面试与实战/03-算法训练/华为简单[31个]/HJ94 记票统计.md"}'),i={name:"posts/前端面试与实战/03-算法训练/华为简单[31个]/HJ94 记票统计.md"};function r(l,a,s,d,h,p){return t(),o("div",null,[...a[0]||(a[0]=[n('<div><h1 id="hj94-记票统计" tabindex="-1">HJ94 记票统计 <a class="header-anchor" href="#hj94-记票统计" aria-label="Permalink to &quot;HJ94 记票统计&quot;">​</a></h1><blockquote><p>本节目标：理解“HJ94 记票统计”的核心思路，并能把它用于实际开发或面试表达。 <strong>描述</strong> 请实现一个计票统计系统。你会收到很多投票，其中有合法的也有不合法的，请统计每个候选人得票的数量以及不合法的票数。 （注：不合法的投票指的是投票的名字不存在n个候选人的名字中！！） 数据范围：每组输入中候选人数量满足 1≤<em>n</em>≤100 ，总票数量满足 1≤<em>n</em>≤100 <strong>输入描述：</strong> 第一行输入候选人的人数n，第二行输入n个候选人的名字（均为大写字母的字符串），第三行输入投票人的人数，第四行输入投票。 <strong>输出描述：</strong> 按照输入的顺序，每行输出候选人的名字和得票数量（以&quot; : &quot;隔开，注：英文冒号左右两边都有一个空格！），最后一行输出不合法的票数，格式为&quot;Invalid : &quot;+不合法的票数。 <strong>示例1</strong> 输入： 4A B C D8A D E CF A GG A B ==复制== 输出： A : 3B : 1C : 0D : 1Invalid : 3 ==复制== 说明： E CF GG三张票是无效的，所以Invalid的数量是3.</p></blockquote><p>为了实现这个计票统计系统，我们可以采取以下步骤：</p><ol><li>读取候选人数量<code>n</code>，然后读取<code>n</code>个候选人的名字，将它们存储在一个字典中，用来记录每个候选人的得票数。初始时，每个候选人的得票数都是0。</li><li>读取投票人的数量，然后读取相应数量的投票。对于每一张票，检查其是否为合法票（即是否在候选人名字列表中）。</li></ol><ul><li>如果合法，对应候选人的得票数加1。</li><li>如果不合法，记录不合法票的数量。</li></ul><ol start="3"><li>按照输入顺序，输出每个候选人的名字和得票数量，以及不合法的票数。</li></ol><p>下面是Python代码示例：</p><h1 id="输入候选人的人数" tabindex="-1">输入候选人的人数 <a class="header-anchor" href="#输入候选人的人数" aria-label="Permalink to &quot;输入候选人的人数&quot;">​</a></h1><p>n = int(input())</p><h1 id="输入候选人的名字" tabindex="-1">输入候选人的名字 <a class="header-anchor" href="#输入候选人的名字" aria-label="Permalink to &quot;输入候选人的名字&quot;">​</a></h1><p>candidates = input().split()</p><h1 id="初始化候选人得票数字典" tabindex="-1">初始化候选人得票数字典 <a class="header-anchor" href="#初始化候选人得票数字典" aria-label="Permalink to &quot;初始化候选人得票数字典&quot;">​</a></h1><p>votes = {name: 0 for name in candidates}</p><h1 id="初始化无效票计数" tabindex="-1">初始化无效票计数 <a class="header-anchor" href="#初始化无效票计数" aria-label="Permalink to &quot;初始化无效票计数&quot;">​</a></h1><p>invalid_votes = 0</p><h1 id="输入投票人的人数" tabindex="-1">输入投票人的人数 <a class="header-anchor" href="#输入投票人的人数" aria-label="Permalink to &quot;输入投票人的人数&quot;">​</a></h1><p>m = int(input())</p><h1 id="输入投票" tabindex="-1">输入投票 <a class="header-anchor" href="#输入投票" aria-label="Permalink to &quot;输入投票&quot;">​</a></h1><p>voting = input().split()</p><h1 id="遍历投票-统计票数" tabindex="-1">遍历投票，统计票数 <a class="header-anchor" href="#遍历投票-统计票数" aria-label="Permalink to &quot;遍历投票，统计票数&quot;">​</a></h1><p>for vote in voting: if vote in votes: votes[vote] += 1 else: invalid_votes += 1</p><h1 id="输出每个候选人的得票数" tabindex="-1">输出每个候选人的得票数 <a class="header-anchor" href="#输出每个候选人的得票数" aria-label="Permalink to &quot;输出每个候选人的得票数&quot;">​</a></h1><p>for name in candidates: print(f&quot;{name} : {votes[name]}&quot;)</p><h1 id="输出无效票数" tabindex="-1">输出无效票数 <a class="header-anchor" href="#输出无效票数" aria-label="Permalink to &quot;输出无效票数&quot;">​</a></h1><p>print(f&quot;Invalid : {invalid_votes}&quot;)</p><p>这段代码首先创建一个字典<code>votes</code>，其中包含所有候选人及其初始得票数（0）。然后，它遍历所有投票，对于每一张投票，如果是合法票（即投给了存在的候选人），则增加相应候选人的得票数；如果是不合法票（即投给了不存在的候选人），则增加不合法票数的计数。最后，按顺序输出每个候选人及其得票数，以及不合法票数。</p></div>',1)])])}const m=e(i,[["render",r]]);export{u as __pageData,m as default};
